// Auto Grading System
const submission = $input.first().json;

// Extract student info
const studentName = submission['Họ tên'] || submission['Tên'] || submission['name'] || 'Unknown';
const studentId = submission['Mã HS'] || submission['ID'] || submission['student_id'] || 'N/A';
const quizName = submission['Bài quiz'] || submission['Quiz'] || submission['quiz_name'] || 'Unknown';

// Parse answers
const answers = {};
for (const [key, value] of Object.entries(submission)) {
  if (key.startsWith('Câu') || key.startsWith('Q') || key.startsWith('Answer')) {
    answers[key] = value?.toString().trim().toLowerCase() || '';
  }
}

// Answer key (customize this for each quiz)
const answerKey = {
  'Câu 1': 'a',
  'Câu 2': 'b',
  'Câu 3': 'c',
  'Câu 4': 'd',
  'Câu 5': 'a',
  'Câu 6': 'b',
  'Câu 7': 'c',
  'Câu 8': 'a',
  'Câu 9': 'd',
  'Câu 10': 'b'
};

// Grade answers
let correct = 0;
const total = Object.keys(answerKey).length;
const results = [];

for (const [question, correctAnswer] of Object.entries(answerKey)) {
  const studentAnswer = answers[question] || '';
  const isCorrect = studentAnswer === correctAnswer.toLowerCase();

  if (isCorrect) correct++;

  results.push({
    question,
    correct_answer: correctAnswer,
    student_answer: studentAnswer || '(không trả lời)',
    is_correct: isCorrect
  });
}

const score = (correct / total) * 10;
const scoreRounded = Math.round(score * 100) / 100;
const percentage = (correct / total) * 100;

// Grade classification
let grade, gradeVN, message;
if (percentage >= 90) {
  grade = 'A';
  gradeVN = 'Xuất sắc';
  message = '🎉 Tuyệt vời! Bạn đã làm rất tốt!';
} else if (percentage >= 80) {
  grade = 'B';
  gradeVN = 'Giỏi';
  message = '👏 Làm tốt lắm! Tiếp tục phát huy!';
} else if (percentage >= 70) {
  grade = 'C';
  gradeVN = 'Khá';
  message = '👍 Khá tốt! Hãy ôn thêm để cải thiện!';
} else if (percentage >= 50) {
  grade = 'D';
  gradeVN = 'Trung bình';
  message = '📚 Cần ôn tập thêm. Đừng nản lòng!';
} else {
  grade = 'F';
  gradeVN = 'Yếu';
  message = '💪 Hãy xem lại bài và làm lại nhé!';
}

return [{
  json: {
    student_name: studentName,
    student_id: studentId,
    quiz_name: quizName,
    score: scoreRounded,
    score_formatted: `${scoreRounded}/10`,
    percentage: percentage.toFixed(1),
    correct,
    total,
    grade,
    grade_vn: gradeVN,
    message,
    results,
    submitted_at: submission['Timestamp'] || submission['Thời gian'] || new Date().toISOString(),
    timezone: 'Asia/Ho_Chi_Minh',
    graded_at: new Date().toISOString()
  }
}];

